### 實戰：九九乘法表

預期輸出：

```
1*1=1
1*2=2
...
1*9=9
2*1=2
...
9*9=81
```

首先用簡化法，產生 `1*1 ~ 1*9`：

```js
for (let i = 1; i <= 9; i += 1) {
  console.log('1*' + i '=' + 1*i )
}
```

包成函式，把 1 換成 k：

```js
function printTable(k) {
  for (let i = 1; i <= 9; i += 1) {
    console.log(k + '*' + i + '=' + k*i )
  }
}

printTable(1)
printTable(2)
...
printTable(9)
// 即可產生九九乘法表
```

其實就是再一個迴圈：

```js
function printTable(k) {
  for (let i = 1; i <= 9; i += 1) {
    console.log(k + "*" + i + "=" + k * i);
  }
}

// 這個會產生 1~9
for (let k = 1; k <= 9; k += 1) {
  printTable(k);
}
// 結果：產生 1*1~9*9
```

但總有一天要學會雙層迴圈，試著把上面的寫法合併：

```js
// 這個產生 1~9
for (let k = 1; k <= 9; k += 1) {
  // 這個也產生 1~9
  for (let i = 1; i <= 9; i += 1) {
    console.log(k + "*" + i + "=" + k * i);
  }
}
```

我們可以利用 Debugger 來觀察雙層迴圈如何執行。也就是先執行外層迴圈第一圈，然後進入內層迴圈第一到九圈，執行完再回到外層迴圈第二圈，依序執行下去，用文字表示如下：

```
k=1 i=1, 2, 3...9
k=2 i=1, 2, 3...9
k=3 i=1, 2, 3...9
...
k=9 i=1, 2, 3...9
```

### 實戰：印出 1~100 平方數

簡化法：先印出 1~100

```js
for (let i = 1; i <= 100; i += 1) {
  console.log(i);
}
```

搭配函式填空法

```js
for (let i = 1; i <= 100; i += 1) {
  if (isSquare) {
    console.log(i);
  }
}

function isSquare(n) {}
```

那麼，該如何判斷平方數呢？

開根號：`Math.sqrt(n)`
無條件捨去：`Math.floor(n)`

將 n 開根號後得到的數字，無條件捨去後再相乘，若還是等於 n 則為平方數。

```js
for (let i = 1; i <= 100; i += 1) {
  if (isSquare) {
    console.log(i);
  }
}

function isSquare(n) {
  let root = Math.floor(Math.sqrt(n));
  return root * root === n; // 成立得到 true；反之得到 false
}
```

另一種想法：印出平方數，直到超過 100 為止。

```js
let i = 1;
while (i * i <= 100) {
  console.log(i * i);
  i += 1;
}
```

### 作業檢討：印出聖誕樹

[LIOJ 1023：印出聖誕樹](https://oj.lidemy.com/problem/1023?_ga=2.105028611.1291128142.1593271357-1977277931.1590338596)

```js
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
});

const lines = [];

// 讀取到一行，先把這一行加進去 lines 陣列，最後再一起處理
rl.on("line", (line) => {
  lines.push(line);
});

function isPrime(n) {
  if (n === 1) {
    return false;
  }
  for (let i = 2; i < n; i += 1) {
    if (n % i === 0) {
      return false;
    }
  }
  return true;
}

// 前面已宣告過 lines，這裡改用 input 作為參數，拿取內容 lines
function solve(input) {
  let n = Number(input[0]);
  for (let i = 1; i <= n; i += 1) {
    printTree(i, n);
  }
  for (let i = 1; i <= n - 1; i += 1) {
    printBottom(n);
  }
}

function printTree(i, n) {
  console.log(repeat(" ", n - i) + repeat("*", 2 * i - 1));
}

function printBottom(n) {
  console.log(repeat(" ", n - 1) + "|");
}

function repeat(str, n) {
  let result = "";
  for (let i = 1; i <= n; i += 1) {
    result += str;
  }
  return result;
}

// 輸入結束，開始針對 lines 做處理
rl.on("close", () => {
  solve(lines);
});
```

