### [LIOJ 1033：最近點對](https://oj.lidemy.com/problem/1033)

```js
// 利用平面距離計算得到的函式
function distance(x1, y1, x2, y2) {
  let dis = Math.sqrt(
    abs(x1 - x2) * abs(x1 - x2) + abs(y1 - y2) * abs(y1 - y2)
  );
  return dis; // 取到小數點第二位
}

function abs(n) {
  if (n < 0) {
    return -n;
  }
  return n;
}

function solve(input) {
  let n = Number(input[0]);
  let dots = [];
  for (let i = 1; i < input.length; i += 1) {
    let temp = input[i].split(" ");
    dots.push({
      x: Number(temp[0]),
      y: Number(temp[1]),
    });
  }

  let min = Infinity; // 最短距離先設一個最大值
  let ans = null;
  for (let i = 0; i < dots.length; i += 1) {
    for (let j = i + 1; j < dots.length; j += 1) {
      let dis = distance(dots[i].x, dots[i].y, dots[j].x, dots[j].y);
      if (dis < min) {
        min = dis;
        ans = {
          x1: dots[i].x,
          y1: dots[i].y,
          x2: dots[j].x,
          y2: dots[j].y,
        };
      }
    }
  }

  if (ans.x1 > ans.x2) {
    console.log(ans.x2 + " " + ans.y2);
    console.log(ans.x1 + " " + ans.y1);
  } else if (ans.x1 < ans.x2) {
    console.log(ans.x1 + " " + ans.y1);
    console.log(ans.x2 + " " + ans.y2);
  } else {
    if (ans.y1 > ans.y2) {
      console.log(ans.x2 + " " + ans.y2);
      console.log(ans.x1 + " " + ans.y1);
    } else {
      console.log(ans.x1 + " " + ans.y1);
      console.log(ans.x2 + " " + ans.y2);
    }
  }
}
