function whoWin(input) {
  // 判斷橫的三排
  for (let i = 0; i < 3; i += 1) {
    if (input[i][0] === input[i][1] && input[i][1] === input[i][2]) {
      return input[i][0];
    }
  }
  // 判斷直的三排
  for (let i = 0; i < 3; i += 1) {
    if (input[0][i] === input[1][i] && input[1][i] === input[2][i]) {
      return input[0][i];
    }
  }
  // 判斷斜對角
  if (input[0][0] === input[1][1] && input[1][1] === input[2][2]) {
    return input[0][0];
  }
  if (input[0][2] === input[1][1] && input[1][1] === input[2][0]) {
    return input[1][1];
  }

  return "DRAW";
}
