// LIOJ 1042：String toLowerCase
function toLowerCase(str) {
  let result = "";
  for (let i = 0; i < str.length; i += 1) {
    if (str[i] >= "A" && str[i] <= "Z") {
      let code = str.charCodeAt(i);
      result += String.fromCharCode(code + 32);
    } else {
      result += str[i]; // 若不是大寫就直接加到字串
    }
  }
  return result;
}

