const Brand = styled.h1`
  margin: 0;
`;

const NavbarList = styled.ul`
  display: flex;
  align-items: center;
  list-style-type: none;
  text-decoration: none;
  margin: 0;
  padding: 0;
`;

const Nav = styled(Link)`
  height: 58px;
  width: 100px;
  display: flex;
  justify-content: center;
  align-items: center;
  text-decoration: none;
  color: #666;

  ${(props) =>
    props.$active &&
    `
      background: #eee;
      color: #222;
  `}
`;

const LeftNavbar = styled.div`
  display: flex;
  align-items: center;

  /* 代表在 LeftNavbar 底下的 NavbarList */
  ${NavbarList} {
    margin-left: 32px;
  }
`;

export default function Header() {
  // 可拿到目前路徑
  const location = useLocation();

  return (
    <HeaderContainer>
      <LeftNavbar>
        <Brand>
          <Link exact to="/">
            React 部落格
          </Link>
        </Brand>
        <NavbarList>
          <Nav to="/" $active={location.pathname === "/"}>
